import 'package:dio/dio.dart';
import 'package:dio_refresh/dio_refresh.dart';

void main() {
  final dio = Dio();
  final tokenManager = TokenManager.instance;

  dio.interceptors.add(DioRefreshInterceptor(
    tokenManager: tokenManager,
    authHeader: (tokenStore) => {'Authorization': 'Bearer ${tokenStore.accessToken}'},
    shouldRefresh: (response) => response?.statusCode == 401,
    onRefresh: (dio, tokenStore) async {
      final response = await dio.post('/refresh', data: {'refresh_token': tokenStore.refreshToken});
      return TokenStore(accessToken: response.data['accessToken'], refreshToken: response.data['refreshToken']);
    },
  ));
}
